<?php
require_once 'includes/core.php'; $o = row('SELECT * FROM orders WHERE order_no=?', [$_GET['no'] ?? '']);
if (!$o || !(is_staff() || (user() && user()['id'] == $o['user_id']))) { http_response_code(403); die('Not allowed'); }
$its = rows('SELECT * FROM order_items WHERE order_id=?', [$o['id']]); ?>
<!DOCTYPE html><html><head><meta charset="utf-8"><title>Invoice <?= e($o['order_no']) ?></title><style>body{font-family:Arial,sans-serif;max-width:760px;margin:30px auto;color:#222}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left}.r{text-align:right}h1{color:#1f5c3a}@media print{.np{display:none}}</style></head><body>
<button class="np" onclick="print()">🖨 Print</button><p><img src="<?= e(has_img(S('logo')) ? img(S('logo')) : asset('img/logo-mark.png')) ?>" alt="" height="54"></p><h1>Invoice</h1><p><?= e(S('address_en')) ?><br><?= e(S('phone')) ?> · <?= e(S('email')) ?></p><hr>
<p><b>Order:</b> <?= e($o['order_no']) ?><br><b>Date:</b> <?= date('d M Y h:i A', strtotime($o['created_at'])) ?><br><b>Bill to:</b> <?= e($o['name']) ?>, <?= e($o['phone']) ?><br><?= e($o['address']) ?>, <?= e($o['city']) ?><br><b>Payment:</b> <?= e(strtoupper($o['payment_method'])) ?> (<?= e($o['payment_status']) ?>)</p>
<table><tr><th>Item</th><th class="r">Price</th><th class="r">Qty</th><th class="r">Total</th></tr><?php foreach ($its as $i) echo '<tr><td>' . e($i['name']) . ($i['variant'] ? ' (' . e($i['variant']) . ')' : '') . '</td><td class="r">' . money($i['price']) . '</td><td class="r">' . $i['qty'] . '</td><td class="r">' . money($i['price'] * $i['qty']) . '</td></tr>'; ?>
<tr><td colspan="3" class="r">Subtotal</td><td class="r"><?= money($o['subtotal']) ?></td></tr><tr><td colspan="3" class="r">Delivery<?= $o['delivery_zone'] ? ' (' . ($o['delivery_zone'] === 'inside' ? 'Inside Dhaka' : 'Outside Dhaka') . ')' : '' ?></td><td class="r"><?= money($o['shipping']) ?></td></tr><tr><td colspan="3" class="r">Discount</td><td class="r">-<?= money($o['discount']) ?></td></tr><tr><td colspan="3" class="r"><b>Total</b></td><td class="r"><b><?= money($o['total']) ?></b></td></tr></table><p>Thank you for shopping with us!</p></body></html>
